solution.code:
function typeName(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

console.log(typeName(null));
console.log(typeName([1, 2]));
console.log(typeName(42));
console.log(typeName('hi'));

brokenCode.code:
const original = { name: 'Ada', scores: [10, 20] };
const copy = original; // intended as an independent copy
copy.name = 'Grace';
console.log(original.name); // expected 'Ada' but logs 'Grace'

solution.code:
const original = { name: 'Ada', scores: [10, 20] };
const copy = { ...original }; // shallow copy — new object
copy.name = 'Grace';
console.log(original.name); // 'Ada' — unchanged
console.log(copy.name);     // 'Grace'

function tweak(num, obj) {
  num = num + 1;   // local copy only
  obj.value = obj.value + 1; // mutates shared object
}

let n = 10;
const o = { value: 10 };
tweak(n, o);
console.log(n);       // 10 — unchanged
console.log(o.value); // 11 — changed
